$ErrorActionPreference='Stop'
$Here=Split-Path -Parent $MyInvocation.MyCommand.Path
$Source=Join-Path $Here 'staged'
$Updates=Join-Path $Here 'distribution\updates'
$Version=(Get-Content -Raw (Join-Path $Source 'app\release_info.json') | ConvertFrom-Json).app_version
$Exclude=@('tests','archive','distribution','.venv','__pycache__')
New-Item -ItemType Directory -Force -Path $Updates|Out-Null
$Stage=Join-Path $Updates 'LabTools'
if(Test-Path $Stage){Remove-Item -LiteralPath $Stage -Recurse -Force}
Copy-Item -LiteralPath $Source -Destination $Stage -Recurse
Get-ChildItem -LiteralPath $Stage -Directory -Recurse -Force|
 Where-Object{$_.Name-in$Exclude}|Sort-Object FullName -Descending|
 Remove-Item -Recurse -Force
$Zip=Join-Path $Updates "WINK_App_Update_v$Version.zip"
if(Test-Path $Zip){Remove-Item -LiteralPath $Zip -Force}
Compress-Archive -LiteralPath $Stage -DestinationPath $Zip -CompressionLevel Optimal
$Hash=(Get-FileHash -Algorithm SHA256 -LiteralPath $Zip).Hash.ToLowerInvariant()
[ordered]@{
 app_version=$Version
 package_filename=(Split-Path -Leaf $Zip)
 package_sha256=$Hash
 # 1.1.0 adds magpylib to the environment. The updater swaps app files only -
 # it never runs pip - so a machine on runtime 1.0.0 that took this update
 # would get magnetotaxis code whose dependency is still absent. Gating it
 # sends those machines to Setup_Lab_Tools.bat instead of half-updating them.
 # UNCHANGED for 11.125: that release adds no libraries, so a machine already
 # on 1.1.0 takes it with a click and needs no second visit to the installer.
 min_runtime_version='1.1.0'
 changelog='v11.138 Cell viewer folder scan, opt-in fine-texture tracking, and a publish system that cannot lie about itself. The cultured cell viewer reads folders it previously reported as empty: the scan globbed *.tif, which does not match .tiff, so a folder of 3,676 Basler frames came back as nothing and the report read 0 images, 1 frame each - a count of zero carrying a per-item figure. Extensions are now matched explicitly and case-folded rather than left to the platform, because Path.glob is case-insensitive on Windows and case-sensitive on macOS, so a folder of .TIF files would have worked here and failed silently on the lab's Mac. TIFF series are assembled as one recording by filename sequence number rather than counted as N single-frame recordings, and absolute-time measures are gated on a declared frame interval: nothing assumes a rate. The single-worm tracker can use the validated fine-texture foreground rule with --foreground fine-texture; LEGACY REMAINS THE DEFAULT until the six frozen recordings are baselined. On 234 frames the texture rule found the animal on every one where the legacy rule returned about 1,400 fragments per frame, but the acceptance band admitted only 3, so the band is the binding constraint and is recorded as underived rather than tuned to make the test pass. Publishing is now one command that refuses a dirty tree, unpushed commits, a stale release stamp or failing checks, writes a NEW versioned tree that never overwrites a published one, and verifies its own output against the same version tripwire the Hub uses. The Hub no longer relaunches itself from a different tree mid-session: an update changes the next launch, never the running session, and the version shown is derived from the tree actually running rather than from an install-time file that could name a version the code did not have. Student builds carry a crash handler that writes a full traceback with build, commit, machine and interpreter to a log on the L drive. A standing insight scanner checks the codebase against nine rules drawn from this project's own incidents. BUILD_APP_UPDATE.ps1 is retired in favour of publish_release.py, which is now the single writer of both the published tree and the update manifest. v11.137 The Hub keeps its text and its buttons when the window is resized, and the calcium tool reads Leica .lif files. Category names were being cut off mid-word, because a Treeview column carries its own width independent of the widget holding it and Tk defaults it to about 200 pixels. Unlike a clipped label there was nothing to reveal the rest: no wrapping, no ellipsis, no horizontal scrollbar, and widening the pane did not help because the column stayed 200 pixels wide inside a wider widget. The column now follows its pane. Separately, ttk.Panedwindow has no per-pane minimum, that option having existed on the older tk.PanedWindow and not survived into the themed one, so a narrow window or a dragged sash pushed the detail pane past the edge and took the Launch button with it. Sash positions are now clamped after every resize so each pane keeps a usable width. The rail floor is MEASURED from the longest category name rather than guessed: a guess of 190 pixels passed every clamp check and still cut Motor output - Sensory-guided behaviour in half, so the floor is computed from the text and comes out at 300. Categories get added over time and the floor follows them. All of this is tested against a real window at four widths rather than reasoned about, because Tk geometry is what it does and not what the code says. The calcium tool now reads Leica .lif files directly, listing every series with its frame count, frame rate and duration taken from the file header. It also no longer answers the question what can this data support from a typed form field: pointed at a 224 frame movie with the frames box left at its default of 1, it had reported that every kinetic measurement was impossible because the recording was a single frame. Frame count, frame rate and bit depth are read from the data, and the operator declares only what the file cannot know, which probe and which channel is which. Movies are segmented on the time average rather than one frame, because a cell that is dark at rest and fires once is dimmer than its silent neighbour in a resting frame, so a tool segmenting there ranks the two the wrong way round and then reports that the cell it happened to find was the one that responded. A new warning flags any series in which every measurable cell scores as responding, because real responses are rarely unanimous. v11.136 An empty recording must not produce a dose-response. The new calcium tool was run on the lab ACh dose-response movies and reported that 100 percent of cells responded in every well, including caffeine, with dF/F0 up to 32, which looked like a dose-response curve. None of it was real. In those recordings 96 to 98 percent of every pixel is exactly zero, only 24 to 43 of 256 grey levels are used, the whole-field mean is 0.4 counts, and in the brightest frame of the strongest condition the objects above 5 counts numbered 1121 with a median size of one pixel, which is shot noise and not cells. Cell baselines came out between 0.00 and 2.87 counts, and dF/F0 divides by that, so one grey level becomes an amplitude of 10. Time to peak was scattered across the whole recording instead of clustering after drug addition, and decay constants came back at 121 to 151 seconds from a 30 second recording. Both are signatures of no event at all. The existing guards missed it because check_recording warns about dim signal and low bit depth and resting_ratio refuses ratios built on too few counts, but both check a RECORDING while transient takes a TRACE, so nothing stood between a trace and dF/F0. transient now refuses a trace whose baseline is indistinguishable from zero, using a unit-free test that needs no declared bit depth: it compares the baseline against the scatter of the resting part of the trace itself, and if the resting points wander by as much as the baseline is worth then the baseline is not measurably different from zero. The refusal says to fix the exposure, because this is not a threshold to tune. A companion test confirms the guard does not refuse real data, since a genuine transient on a baseline of 100 counts with a standard deviation of 3 still passes. v11.135 Calcium in cultured human muscle cells. A new tool under Physiology, Cultured cell calcium (probe-aware), for the lab work from myoblasts to myofibres and from striated to smooth muscle. It asks which probe was used and refuses the measurements that probe cannot support, along three axes that fail independently: whether two cells can be compared on raw signal (Fura-2 cancels dye loading, Fluo-4 does not), whether the signal comes back down, and whether there is any time in the sample at all. The middle axis is the one a single ratiometric flag cannot see. A decay constant fitted to MitoSOX fits perfectly and means nothing, because its oxidised product intercalates DNA and stays, so the curve is an accumulation and not a response; that is now refused and an accumulation rate offered in its place. Antibody staining is refused every kinetic measure however many frames are supplied, because frames of a fixed slide are not time. Fifteen probes are registered, each with the caveat that decides how its numbers read: TMRM changes sign between quench and non-quench mode, the roGFP and HyPer sensors are pH-sensitive, and a Fura-2 ratio is not a calcium concentration until it is calibrated on that rig. For the shRNA knockdown layout, where one channel is calcium and the other marks transfected cells, the untransfected cells in the SAME field are the control, because they share the coverslip, the loading, the illumination and the focus. Each transfected cell is normalised to the median of the untransfected cells in its own field. The untransfected cells are also reported as a null band, since that is how much one cell differs from another with no treatment at all, and without it a 1.3-fold difference looks like a result. Three guards cover artefacts that point the same way as the hypothesis: segmenting on the calcium channel finds only the bright cells and so removes exactly the cells carrying the effect, mCherry bleeding into the green detector raises transfected cells optically, and a scramble control that does not sit at unity means transfection itself moved the signal. Step one reports what a recording can support before anything is measured. Cells near the marker threshold are held out as ambiguous rather than forced into a class, and bimodality is measured as Otsu separability, which has a known reference: a single normal distribution cut in half scores 0.64. v11.134 Interface fixes and honest pBoc counts. The Hub control row now WRAPS when the window is narrowed instead of silently dropping the buttons that no longer fit. Tk pack does not wrap, so widgets were not clipped or shrunk but simply absent, leaving a tidy row with things missing from it and nothing to signal the loss. Tool descriptions follow the width of their pane rather than a fixed wrap set once, so they no longer overflow when the pane is narrowed or waste space when it is widened. Windows have a minimum size, because wrapping keeps controls reachable and a floor keeps them legible. An optional LCARS theme can be switched on from the Hub: off by default, remembered per machine, and fully reversible. The defecation detector now REPORTS ITS OWN MERGES. Contractions closer than five seconds were being folded into one another silently, so an animal with a fast cycle was undercounted with nothing in the output to say so. merge_report now states how many were absorbed and what the true upper bound on the count therefore is, which periodicity alone cannot reveal, because an event absorbed beside a neighbour leaves the interval structure untouched. A two-pass rescan re-examines only the windows where the rhythm of that animal says an event went missing, so a regular animal is never rescanned and nothing about it can change. That is what makes it safe across genotypes, where loosening a global threshold would not be. Per-segment curvature is now measured over a baseline that is a fixed fraction of body length rather than the handful of midline points inside each segment, which was reporting tracing jitter rather than posture. A hand correction in the neuron tracker propagates to the frames after it instead of fixing the displayed frame alone. Two tools that were built but never reachable are now in the Hub: pharynx template placement, and GCaMP segmentation calibration.'
}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $Updates 'update_manifest.json') -Encoding UTF8
Remove-Item -LiteralPath $Stage -Recurse -Force
Write-Output "Built application update: $Zip"
